package main

// Learn cards for data languages: SQL and XML (with SVG). Same layout as
// the CSS card in learn_css.go.

var learnSQL = learnTopic{
	Name:   "SQL",
	Match:  []string{"sql", "postgresql sql dialect", "mysql", "plpgsql", "transactsql", ".sql"},
	Source: "PostgreSQL 18 docs (SELECT, INSERT, UPDATE, MERGE, CREATE TABLE, constraints, comparison and conditional functions, joins, window functions, transactions, EXPLAIN, lexical structure, release 15) · PostgreSQL wiki 'Don't Do This' · SQLite (UPSERT, RETURNING, expressions, SELECT) · MySQL 8.4 (identifiers, <=>, ON DUPLICATE KEY UPDATE) · OWASP SQL Injection Prevention · SQLFluff docs",
	Sections: []learnSection{
		{Title: "Reading rows", Keys: []string{"select", "from", "where"}, Items: []learnItem{
			{Use: "SELECT id, title FROM books", Keys: []string{"select", "from"}, Why: "Name the columns you need. The result is a table of rows.",
				Like: "Like asking a librarian for the title and shelf number of each book, not for the books themselves.", Example: "SELECT id, title, price\nFROM books\nWHERE author_id = 42;"},
			{Use: "WHERE price > 10", Keys: []string{"where", "and", "or"}, Why: "Keeps only the rows where the condition is true. Rows where it is false or NULL are left out.",
				Like: "Like a sieve: only what fits through the holes reaches the bowl.", Example: "SELECT id, name FROM products\nWHERE price > 10 AND category = 'books';"},
			{Use: "ORDER BY created_at DESC", Keys: []string{"order", "asc", "desc"}, Why: "Sets the order of the rows. Without ORDER BY, SQL does not promise any order.",
				Like: "Like asking for the post sorted by date. If you do not ask, it comes in whatever order it was picked up.", Example: "SELECT id, title FROM posts\nORDER BY created_at DESC;"},
			{Use: "LIMIT n · FETCH FIRST n ROWS ONLY", Keys: []string{"limit", "fetch", "offset", "rows", "only"}, Why: "Returns only the first n rows. LIMIT works in PostgreSQL, MySQL and SQLite. FETCH FIRST is the SQL:2008 standard form. Use it with ORDER BY, or the rows you get are unpredictable.",
				Like: "Like 'the first ten people in the queue'. It only makes sense once people stand in a set order.", Example: "SELECT id, title FROM posts\nORDER BY created_at DESC\nLIMIT 10;"},
			{Use: "CASE WHEN … THEN … ELSE … END", Keys: []string{"case", "when", "then", "else", "end"}, Why: "An if/else inside a query. The first WHEN that is true gives the value. With no ELSE and no match, the value is NULL.",
				Like: "Like a sorting desk at the post office: each parcel goes to the first slot whose rule fits it.", Example: "SELECT name,\n  CASE WHEN qty = 0 THEN 'out' ELSE 'in' END AS stock\nFROM products;"},
		}},
		{Title: "Joining and grouping", Keys: []string{"join", "on", "group", "by"}, Items: []learnItem{
			{Use: "JOIN orders o ON o.user_id = u.id", Keys: []string{"join", "inner", "on", "using"}, Why: "Combines each row with the rows of the other table where the ON condition is true. JOIN means INNER JOIN.",
				Like: "Like matching each coat ticket to its coat: only pairs that belong together come out.", Example: "SELECT u.name, o.total\nFROM users u\nJOIN orders o ON o.user_id = u.id;"},
			{Use: "LEFT JOIN", Keys: []string{"left", "outer", "right"}, Why: "Keeps every row of the left table. Where nothing matches, the right table's columns are NULL. A filter on the right table goes in ON; in WHERE it removes those rows again.",
				Like: "Like a class list with homework marks: every pupil is listed, and a missing mark stays blank.", Example: "SELECT u.name, o.id AS order_id\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id;"},
			{Use: "GROUP BY … HAVING count(*) > 1", Keys: []string{"group", "having", "count", "sum", "avg", "min", "max"}, Why: "GROUP BY makes one row per group. WHERE filters rows before grouping. HAVING filters the groups after.",
				Like: "Like sorting coins into piles by value, then keeping only the piles with more than one coin.", Example: "SELECT email, count(*)\nFROM users\nGROUP BY email HAVING count(*) > 1;"},
			{Use: "WITH recent AS (SELECT …)", Keys: []string{"with", "recursive", "cte"}, Why: "A named subquery (common table expression). The main query reads it like a table. Use it to split a long query into named steps.",
				Like: "Like preparing chopped onions in a labelled bowl before you start the main recipe.", Example: "WITH recent AS (SELECT * FROM orders\n  WHERE created_at > now() - interval '7 days')\nSELECT user_id, count(*) FROM recent GROUP BY user_id;"},
			{Use: "OVER (PARTITION BY … ORDER BY …)", Keys: []string{"over", "partition", "row_number", "rank", "window"}, Why: "A window function: a total, average or rank over related rows. Unlike GROUP BY, every row is kept.",
				Like: "Like writing each runner's place next to their name. The race list stays complete.", Example: "SELECT name, dept, salary,\n  rank() OVER (PARTITION BY dept ORDER BY salary DESC)\nFROM employees;"},
		}},
		{Title: "NULL: the unknown value", Keys: []string{"null"}, Items: []learnItem{
			{Use: "IS NULL · IS NOT NULL", Keys: []string{"null", "is", "isnull", "notnull"}, Why: "The way to test for NULL. x = NULL gives NULL (unknown), never true. NULL means 'not known', so two NULLs are not known to be equal.",
				Like: "Like two sealed envelopes: you cannot say they hold the same letter. You can only say 'this one is sealed'.", Example: "SELECT id, email FROM users\nWHERE deleted_at IS NULL;"},
			{Use: "COALESCE(nickname, name)", Keys: []string{"coalesce", "ifnull", "nvl"}, Why: "Gives the first value that is not NULL. Use it for defaults. It is standard SQL; IFNULL and NVL are other databases' names for the same idea.",
				Like: "Like calling a mobile number, then the home number if nobody answers.", Example: "SELECT COALESCE(nickname, name) AS display_name\nFROM users;"},
			{Use: "IS NOT DISTINCT FROM", Keys: []string{"distinct", "<=>"}, Why: "Equal, where NULL counts as a normal value: NULL IS NOT DISTINCT FROM NULL is true. MySQL writes it <=>. SQLite also accepts IS.",
				Like: "Like comparing two empty boxes and agreeing they match because both are empty.", Example: "SELECT id FROM orders\nWHERE coupon_code IS NOT DISTINCT FROM $1;"},
			{Use: "NULLIF(x, '')", Keys: []string{"nullif"}, Why: "Gives NULL when the two values are equal, otherwise the first value. NULLIF(x, '') turns empty text into NULL.",
				Like: "Like crossing out a form field that says 'n/a', so it counts as not filled in.", Example: "INSERT INTO contacts (name, phone)\nVALUES ($1, NULLIF($2, ''));"},
		}},
		{Title: "Changing rows", Keys: []string{"insert", "update", "delete", "set", "values"}, Items: []learnItem{
			{Use: "INSERT INTO t (a, b) VALUES (…)", Keys: []string{"insert", "into", "values"}, Why: "Always list the columns. Without the list, the values go into the columns in the table's own order.",
				Like: "Like labelling each box when you move house, instead of trusting the order they leave the van.", Example: "INSERT INTO users (email, name)\nVALUES ('ann@example.com', 'Ann');"},
			{Use: "UPDATE t SET a = 1 WHERE id = 7", Keys: []string{"update", "set"}, Why: "Changes the rows that match WHERE. With no WHERE, every row in the table changes.",
				Like: "Like repainting one door by its number. Forget the number, and every door in the street is repainted.", Example: "UPDATE users\nSET name = 'Ann', updated_at = now()\nWHERE id = 7;"},
			{Use: "DELETE FROM t WHERE id = 7", Keys: []string{"delete"}, Why: "Removes the rows that match WHERE. With no WHERE, every row is removed.",
				Like: "Like throwing out one named file. Without the name, the whole cabinet is emptied.", Example: "DELETE FROM sessions\nWHERE expires_at < now();"},
			{Use: "ON CONFLICT (id) DO UPDATE", Keys: []string{"conflict", "excluded", "upsert", "nothing", "duplicate"}, Why: "Insert, or update the row that already exists (an upsert). EXCLUDED.col is the value you tried to insert. PostgreSQL, and SQLite 3.24+. MySQL writes ON DUPLICATE KEY UPDATE.",
				Like: "Like a guest list: a new name is added, a name already there gets its details updated.", Example: "INSERT INTO stock (sku, qty) VALUES ('A1', 5)\nON CONFLICT (sku)\nDO UPDATE SET qty = EXCLUDED.qty;"},
			{Use: "RETURNING id", Keys: []string{"returning"}, Why: "Gives back values from the rows just inserted, updated or deleted, such as a new id. PostgreSQL, and SQLite 3.35+. Not in the SQL standard.",
				Like: "Like a cloakroom handing you a ticket number as it takes your coat.", Example: "INSERT INTO users (email) VALUES ('ann@example.com')\nRETURNING id;"},
			{Use: "MERGE INTO t USING s ON …", Keys: []string{"merge", "matched"}, Why: "Standard SQL: insert, update or delete rows of t to match a source s, in one statement. PostgreSQL 15+.",
				Like: "Like updating a stock list from a delivery note: new items added, known items changed.", Example: "MERGE INTO stock s USING delivery d ON s.id = d.id\nWHEN MATCHED THEN UPDATE SET qty = s.qty + d.qty\nWHEN NOT MATCHED THEN INSERT (id, qty) VALUES (d.id, d.qty);"},
		}},
		{Title: "Tables and types", Keys: []string{"create", "table", "alter", "not", "constraint", "default"}, Items: []learnItem{
			{Use: "GENERATED ALWAYS AS IDENTITY", Keys: []string{"generated", "identity", "always"}, Why: "An id column the database fills in, from its own counter. Standard SQL; PostgreSQL 10+. Use it instead of serial.",
				Like: "Like a ticket machine at a deli counter: each customer gets the next number.", Example: "CREATE TABLE users (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  email text NOT NULL);"},
			{Use: "PRIMARY KEY", Keys: []string{"primary"}, Why: "The column that names each row. Values must be unique and not NULL. It creates an index by itself.",
				Like: "Like a passport number: one per person, never blank, never shared.", Example: "CREATE TABLE order_items (\n  order_id bigint, product_id bigint,\n  PRIMARY KEY (order_id, product_id));"},
			{Use: "REFERENCES users (id)", Keys: []string{"references", "foreign", "cascade", "restrict"}, Why: "A foreign key: the value must exist in the other table. ON DELETE CASCADE deletes the linked rows too. The column gets no index by itself, so add one.",
				Like: "Like a parcel label that must name a real street. The post office refuses made-up addresses.", Example: "CREATE TABLE orders (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  user_id bigint NOT NULL REFERENCES users (id));"},
			{Use: "text", Keys: []string{"varchar", "char"}, Why: "PostgreSQL: use text for strings. For a length limit, add a CHECK. A fixed varchar(n) limit often causes errors later.",
				Like: "Like a notebook with no line limit. Add a rule only where you really need one.", Example: "CREATE TABLE users (\n  name text NOT NULL CHECK (length(name) <= 100)\n);"},
			{Use: "timestamptz", Keys: []string{"timestamp", "now", "current_timestamp"}, Why: "PostgreSQL: use timestamptz for moments in time. Plain timestamp stores no time zone, so maths across zones or daylight-saving changes goes wrong.",
				Like: "Like writing '9:00 London time' instead of just '9:00' on an invitation.", Example: "CREATE TABLE events (\n  name text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now());"},
			{Use: "numeric(12, 2)", Keys: []string{"numeric", "decimal", "money"}, Why: "Exact decimal numbers. Use it for money. The PostgreSQL money type depends on a locale setting and stores no currency.",
				Like: "Like counting coins one by one instead of weighing the bag.", Example: "CREATE TABLE invoices (\n  id bigint PRIMARY KEY,\n  total numeric(12, 2) NOT NULL);"},
			{Use: "CHECK (qty > 0)", Keys: []string{"check"}, Why: "A rule every row must meet. A row that makes it false is refused. NULL passes.",
				Like: "Like a ride with a height bar: anyone shorter is turned away at the gate.", Example: "CREATE TABLE order_lines (\n  qty integer NOT NULL CHECK (qty > 0),\n  price numeric(12, 2) CHECK (price >= 0));"},
		}},
		{Title: "Safety and speed", Keys: []string{"index", "transaction", "prepare"}, Items: []learnItem{
			{Use: "WHERE id = $1", Keys: []string{"$1", "$2", "?", "prepare", "execute", "parameter"}, Why: "A placeholder. The value travels apart from the SQL text, so input cannot change the query. PostgreSQL numbers them $1, $2; many drivers use ? instead. OWASP's first defence against SQL injection.",
				Like: "Like a form with fixed boxes: whatever someone writes in a box stays an answer, never a new question.", Example: "SELECT id, name FROM users\nWHERE email = $1 AND active = $2;"},
			{Use: "allow-list for names", Keys: []string{"allow-list", "allowlist"}, Why: "Placeholders hold values only, not table names, column names or ASC/DESC. Map the user's choice to a fixed list in your code and refuse anything else.",
				Like: "Like a menu: guests pick a dish by number, they do not write their own recipe for the kitchen.", Example: "if col not in {\"name\", \"price\", \"created_at\"}:\n  col = \"name\"\nsql = f\"SELECT id, name FROM items ORDER BY {col}\""},
			{Use: "BEGIN … COMMIT", Keys: []string{"begin", "commit", "rollback", "savepoint"}, Why: "A transaction: all the statements happen, or none do. ROLLBACK cancels them. Without BEGIN, each statement is its own transaction.",
				Like: "Like a bank transfer: money leaves one account only if it arrives in the other.", Example: "BEGIN;\nUPDATE accounts SET bal = bal - 100 WHERE id = 1;\nUPDATE accounts SET bal = bal + 100 WHERE id = 2; COMMIT;"},
			{Use: "CREATE INDEX ON orders (user_id)", Keys: []string{"index", "unique"}, Why: "Speeds up searches and joins on that column. Index foreign key columns: they are not indexed by themselves.",
				Like: "Like the index at the back of a book: you jump to the page instead of reading every page.", Example: "CREATE INDEX orders_user_id_idx ON orders (user_id);\nCREATE UNIQUE INDEX ON users (lower(email));"},
			{Use: "EXPLAIN ANALYZE", Keys: []string{"explain", "analyze"}, Why: "Shows how the database runs a query and how long each step took. ANALYZE really runs it, so wrap an UPDATE or DELETE in BEGIN … ROLLBACK.",
				Like: "Like a sat-nav replay of your trip: every turn, with the time each one took.", Example: "EXPLAIN ANALYZE\nSELECT * FROM orders WHERE user_id = 42;"},
		}},
		{Title: "Names, quotes and tools", Keys: []string{"--", "\"", "'"}, Items: []learnItem{
			{Use: "snake_case", Keys: []string{"lowercase"}, Why: "Name tables and columns in lower case with underscores. PostgreSQL folds unquoted names to lower case. The SQL standard folds them to upper case.",
				Like: "Like writing every label in the same hand, so nobody files 'Invoices' apart from 'invoices'.", Example: "CREATE TABLE order_items (\n  order_id bigint NOT NULL,\n  unit_price numeric(12, 2));"},
			{Use: "'single quotes'", Why: "Strings use single quotes. To include one, write it twice: 'it''s'.",
				Like: "Like quotation marks around what someone said: they show where the words start and stop.", Example: "SELECT id FROM customers\nWHERE last_name = 'O''Brien';"},
			{Use: "\"double quotes\"", Why: "Double quotes mark a name (an identifier), not text. A quoted name is case-sensitive. MySQL uses `backticks` unless ANSI_QUOTES mode is on.",
				Like: "Like a name badge, not a speech bubble: it says who something is, not what was said.", Example: "SELECT count(*) AS \"Total orders\"\nFROM orders;"},
			{Use: "-- · /* */", Keys: []string{"/*", "*/"}, Why: "-- starts a comment to the end of the line. /* */ is a comment over several lines; in standard SQL these nest.",
				Like: "Like a pencil note in the margin: the reader sees it, the database skips it.", Example: "-- Count active users\nSELECT count(*) FROM users\nWHERE active /* set at signup */;"},
			{Use: "SQLFluff", Keys: []string{"sqlfluff"}, Why: "A linter and formatter for 25+ SQL dialects, including PostgreSQL and T-SQL. sqlfluff lint checks a file; sqlfluff fix corrects many problems.",
				Like: "Like a copy editor who checks spelling and layout before the article is printed.", Example: "sqlfluff lint queries.sql --dialect postgres\nsqlfluff fix queries.sql --dialect postgres"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "SQL built from user input", Keys: []string{"injection", "sprintf", "concat"}, Why: "Joining user text into the SQL string allows SQL injection. Use placeholders. OWASP calls manual escaping strongly discouraged.",
				Like: "Like letting a stranger finish your sentence on a signed cheque.", Example: "-- instead:\nSELECT id, name FROM users WHERE email = $1;"},
			{Use: "x = NULL", Why: "Always gives NULL, so no row matches. Write x IS NULL.",
				Like: "Like asking whether a sealed envelope holds the same letter as another sealed envelope: nobody can say yes.", Example: "-- instead:\nSELECT id FROM users WHERE phone IS NULL;"},
			{Use: "NOT IN (SELECT …)", Keys: []string{"not in", "exists"}, Why: "If the subquery gives any NULL, NOT IN returns no rows. It is also slow on big tables. Use NOT EXISTS.",
				Like: "Like a guest list with one smudged name: the doorman lets nobody in, to be safe.", Example: "-- instead:\nSELECT * FROM users u WHERE NOT EXISTS\n  (SELECT 1 FROM orders o WHERE o.user_id = u.id);"},
			{Use: "BETWEEN on timestamps", Keys: []string{"between"}, Why: "Both ends are included, so a row at exactly midnight counts in two days. Write >= start AND < end.",
				Like: "Like a hotel booking that counts the checkout morning as one more night.", Example: "-- instead:\nSELECT * FROM orders WHERE created_at >= '2026-10-01'\n  AND created_at < '2026-11-01';"},
			{Use: "serial · money · char(n)", Keys: []string{"serial", "bigserial"}, Why: "Older PostgreSQL types with known problems. Use GENERATED … AS IDENTITY, numeric and text instead.",
				Like: "Like old fuses in a new house: they still work, but the new switches are safer.", Example: "-- instead:\nCREATE TABLE items (id bigint GENERATED ALWAYS AS IDENTITY,\n  price numeric(12, 2), code text);"},
			{Use: "\"MixedCase\" names", Why: "A quoted mixed-case name must be quoted every time. Unquoted, it folds to lower case and gives 'does not exist' errors.",
				Like: "Like a door code with capital letters that the keypad cannot type.", Example: "-- instead:\nCREATE TABLE user_accounts (first_name text);\nSELECT first_name FROM user_accounts;"},
		}},
	},
}

var learnXML = learnTopic{
	Name:   "XML / SVG",
	Match:  []string{"xml", ".xml", ".svg", ".xsl", ".xslt", ".plist", ".xaml"},
	Source: "W3C XML 1.0 (Fifth Edition) · Namespaces in XML 1.0 · SVG 2 (Document Structure, Changes) · MDN SVG (getting started, paths, viewBox, use, symbol, title, xlink:href, vector-effect, currentColor) · OWASP XXE Prevention · libxml2 xmllint manual · SVGO README",
	Sections: []learnSection{
		{Title: "Well-formed XML", Keys: []string{"<", ">", "/>"}, Items: []learnItem{
			{Use: "<?xml version=\"1.0\"?>", Keys: []string{"xml", "encoding", "standalone", "<?"}, Why: "The XML declaration. A document should start with it, on the very first line. With no declaration and no byte order mark, the encoding is UTF-8.",
				Like: "Like the label on a tin that says what is inside before you open it.", Example: "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<note>Buy milk</note>"},
			{Use: "one root element", Keys: []string{"root"}, Why: "A document has exactly one root element. Every other element sits inside it.",
				Like: "Like a family tree: it starts from one ancestor at the top.", Example: "<catalog>\n  <book>Dune</book><book>Emma</book>\n</catalog>"},
			{Use: "<x></x> · <x/>", Keys: []string{"</", "/>"}, Why: "Every start tag needs its end tag. An element with no content can be one empty-element tag: <br/>.",
				Like: "Like brackets in maths: every one that opens must close.", Example: "<name>Ann</name>\n<email/>"},
			{Use: "<a><b></b></a>", Keys: []string{"nest", "nesting"}, Why: "Elements nest fully: close the inner one first. <a><b></a></b> is a fatal error, and the parser stops.",
				Like: "Like boxes packed inside boxes: you close the small box before the big one.", Example: "<order>\n  <item><name>Tea</name></item>\n</order>"},
			{Use: "attr=\"v\" · attr='v'", Keys: []string{"=", "attribute"}, Why: "Attribute values are always quoted, with double or single quotes. Each attribute name appears only once in a tag.",
				Like: "Like the fields on a form: each field once, each answer written in its box.", Example: "<book id=\"b1\" lang=\"en\">Dune</book>"},
			{Use: "case-sensitive names", Keys: []string{"case"}, Why: "XML does no case folding. <Item> and <item> are different elements.",
				Like: "Like a password: 'Cat' and 'cat' are not the same.", Example: "<Order>\n  <Item>Tea</Item>\n</Order>"},
		}},
		{Title: "Special characters", Keys: []string{"&", ";"}, Items: []learnItem{
			{Use: "&lt; · &amp; · &gt;", Keys: []string{"lt", "amp", "gt"}, Why: "A literal < or & in text or in an attribute must be written &lt; or &amp;. &gt; writes >.",
				Like: "Like writing 'quote' aloud in a speech, so the listener knows it is not the end of your words.", Example: "<title>Tom &amp; Jerry</title>\n<rule>price &lt; 10</rule>"},
			{Use: "&quot; · &apos;", Keys: []string{"quot", "apos"}, Why: "A \" or ' inside an attribute value that uses the same quote character.",
				Like: "Like quoting a quote: the inner marks must look different from the outer ones.", Example: "<item note=\"She said &quot;hi&quot;\"/>\n<item note='It&apos;s here'/>"},
			{Use: "&#x2014; · &#8212;", Keys: []string{"&#", "x2014", "8212"}, Why: "A character reference by its Unicode number: hex after &#x, decimal after &#. Both of these are the em dash —.",
				Like: "Like ordering by the number on the menu when you cannot say the dish's name.", Example: "<p>&#169; 2026 Example Ltd</p>\n<p>Pages 10&#x2013;12</p>"},
			{Use: "<![CDATA[ … ]]>", Keys: []string{"cdata", "]]>"}, Why: "Text where < and & are not markup. It ends at the first ]]>, so it cannot contain ]]> itself.",
				Like: "Like a glass display case: what is inside is shown exactly as it is, never handled.", Example: "<script><![CDATA[\n  if (a < b && c) run();\n]]></script>"},
			{Use: "<!-- comment -->", Keys: []string{"<!--", "-->", "comment"}, Why: "A comment. The text inside must not contain -- (two hyphens).",
				Like: "Like a sticky note on a document: the reader sees it, the machine ignores it.", Example: "<!-- Database settings -->\n<db host=\"localhost\" port=\"5432\"/>"},
		}},
		{Title: "Namespaces", Keys: []string{"xmlns", "namespace"}, Items: []learnItem{
			{Use: "xmlns=\"uri\"", Keys: []string{"xmlns"}, Why: "The default namespace. Every element name without a prefix, here and inside, belongs to it. xmlns=\"\" removes it again.",
				Like: "Like a country code for every phone number in a book: written once, it applies to all numbers inside.", Example: "<svg xmlns=\"http://www.w3.org/2000/svg\">\n  <circle cx=\"5\" cy=\"5\" r=\"4\"/>\n</svg>"},
			{Use: "xmlns:p=\"uri\" · <p:name>", Keys: []string{"prefix"}, Why: "Binds the prefix p to a namespace. p:name then means 'name' in that namespace. The binding covers this element and everything inside it.",
				Like: "Like a surname: two people called Sam are told apart by their family name.", Example: "<item xmlns:dc=\"http://purl.org/dc/elements/1.1/\">\n  <dc:creator>Ann</dc:creator>\n</item>"},
			{Use: "unprefixed attributes", Why: "The default namespace does not apply to attributes. An attribute without a prefix is in no namespace.",
				Like: "Like a house number: it belongs to the house, not to the street's postcode.", Example: "<book xmlns=\"urn:example:books\" id=\"b1\">\n  <title lang=\"en\">Dune</title>\n</book>"},
			{Use: "namespace URI as a string", Keys: []string{"uri", "http"}, Why: "Namespace names are compared as plain strings. Case and %-escapes count: a different spelling is a different namespace.",
				Like: "Like a key cut for one lock: a key that is almost the same does not open it.", Example: "<svg xmlns=\"http://www.w3.org/2000/svg\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">"},
			{Use: "xml:lang=\"en\" · xml:space", Keys: []string{"lang", "space", "preserve"}, Why: "Built-in attributes. xml:lang names the language; xml:space=\"preserve\" asks to keep whitespace. The xml prefix needs no declaration.",
				Like: "Like the language and 'do not fold' stickers on a parcel: everyone already knows what they mean.", Example: "<p xml:lang=\"fr\">Bonjour</p>\n<code xml:space=\"preserve\">  a = 1</code>"},
		}},
		{Title: "SVG structure", Keys: []string{"svg", "<svg"}, Items: []learnItem{
			{Use: "<svg xmlns=\"…/2000/svg\">", Keys: []string{"<svg", "2000"}, Why: "A standalone .svg file needs the SVG namespace on its root: xmlns=\"http://www.w3.org/2000/svg\".",
				Like: "Like the address on a letter: without it, the post does not know where it belongs.", Example: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\">\n  <circle cx=\"12\" cy=\"12\" r=\"10\"/>\n</svg>"},
			{Use: "viewBox=\"0 0 24 24\"", Keys: []string{"viewbox"}, Why: "The drawing's own coordinates: min-x, min-y, width, height. The drawing is scaled to fit the svg's width and height. A width or height of 0 or less turns drawing off.",
				Like: "Like a map scale: the map is drawn once in its own units, then printed at any size.", Example: "<svg viewBox=\"0 0 24 24\" width=\"48\" height=\"48\">\n  <circle cx=\"12\" cy=\"12\" r=\"10\"/>\n</svg>"},
			{Use: "<g>", Keys: []string{"<g"}, Why: "Groups related shapes, so they can be moved, styled or named together.",
				Like: "Like putting several pieces on one tray to carry them at once.", Example: "<g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n  <path d=\"M4 12h16\"/><path d=\"M12 4v16\"/>\n</g>"},
			{Use: "<defs>", Keys: []string{"<defs"}, Why: "Holds things to reuse, such as gradients, symbols and clip paths. Nothing inside is drawn directly.",
				Like: "Like a cupboard of stencils: they are kept ready, not hung on the wall.", Example: "<defs><clipPath id=\"round\">\n  <circle cx=\"12\" cy=\"12\" r=\"12\"/>\n</clipPath></defs>"},
			{Use: "<symbol id=\"i\" viewBox=…>", Keys: []string{"<symbol"}, Why: "A template that is drawn only through <use>. Give it its own viewBox, so it scales to the size <use> gives it.",
				Like: "Like a rubber stamp: it prints nothing until you press it on the page.", Example: "<symbol id=\"plus\" viewBox=\"0 0 24 24\">\n  <path d=\"M5 12h14M12 5v14\" stroke=\"currentColor\"/>\n</symbol>"},
			{Use: "<use href=\"#i\" x=\"0\" y=\"0\"/>", Keys: []string{"<use", "href"}, Why: "Draws a copy of the element with that id. x and y move the copy.",
				Like: "Like pressing the stamp: each press is one more copy, where you put it.", Example: "<svg width=\"24\" height=\"24\"><use href=\"#plus\"/></svg>\n<svg width=\"48\" height=\"48\"><use href=\"#plus\"/></svg>"},
			{Use: "<title>", Keys: []string{"<title", "<desc", "desc"}, Why: "A short text description for screen readers. Browsers usually show it as a tooltip. Make it the first child of its parent.",
				Like: "Like the caption card beside a painting in a museum.", Example: "<svg viewBox=\"0 0 24 24\" role=\"img\"><title>Close</title>\n  <path d=\"M6 6l12 12M18 6L6 18\" stroke=\"black\"/>\n</svg>"},
		}},
		{Title: "SVG shapes and paint", Keys: []string{"fill", "stroke", "path"}, Items: []learnItem{
			{Use: "<path d=\"M10 10 L20 20 Z\">", Keys: []string{"<path"}, Why: "Any shape. d holds drawing commands: M moves without drawing, L draws a line, H and V draw across and down, Z closes the shape.",
				Like: "Like instructions to a pen plotter: lift and move here, draw to there, back to the start.", Example: "<path d=\"M4 12 L10 18 L20 6\" fill=\"none\" stroke=\"black\"/>"},
			{Use: "M · m (absolute · relative)", Why: "A capital command letter uses absolute coordinates. A small letter is measured from the last point.",
				Like: "Like 'go to number 10' compared with 'walk two doors further'.", Example: "<path d=\"M10 10 h20 v20 h-20 z\"/>"},
			{Use: "C · S · Q · T · A", Why: "Curves. C is a cubic Bézier with two control points, Q a quadratic with one, A an elliptical arc. S and T continue the curve before them smoothly.",
				Like: "Like bending a flexible ruler: the control points are where your fingers push.", Example: "<path d=\"M10 80 C40 10, 65 10, 95 80 S150 150, 180 80\"/>\n<path d=\"M10 50 Q50 0 90 50\"/>"},
			{Use: "<rect> · <circle> · <line>", Keys: []string{"<rect", "<circle", "<ellipse", "<line", "<polyline", "<polygon"}, Why: "Basic shapes. rect takes x, y, width, height; circle takes cx, cy, r; line takes x1, y1, x2, y2.",
				Like: "Like ready-made cookie cutters next to free-hand drawing.", Example: "<rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"4\"/>\n<circle cx=\"12\" cy=\"12\" r=\"5\"/>\n<line x1=\"0\" y1=\"0\" x2=\"24\" y2=\"24\" stroke=\"black\"/>"},
			{Use: "fill · stroke", Keys: []string{"fill", "stroke", "stroke-width", "none"}, Why: "fill paints the inside of a shape; stroke paints its outline. fill=\"none\" leaves the inside empty. Later elements are drawn on top of earlier ones.",
				Like: "Like colouring in a picture, then tracing its outline with a pen.", Example: "<circle cx=\"12\" cy=\"12\" r=\"10\"\n  fill=\"none\" stroke=\"red\" stroke-width=\"2\"/>"},
			{Use: "currentColor", Keys: []string{"currentcolor"}, Why: "The value of the color property. fill=\"currentColor\" makes an icon take the colour set for the text.",
				Like: "Like a chameleon taking the colour of the branch it sits on.", Example: "<svg viewBox=\"0 0 24 24\" fill=\"currentColor\">\n  <path d=\"M12 2 2 22h20z\"/>\n</svg>"},
			{Use: "vector-effect=\"non-scaling-stroke\"", Keys: []string{"vector-effect", "non-scaling-stroke"}, Why: "The outline keeps its width when the shape is scaled or zoomed. Widely supported in browsers since July 2020.",
				Like: "Like a pen line on a balloon that stays thin as the balloon is blown up.", Example: "<path d=\"M0 0 L100 100\" stroke=\"black\"\n  vector-effect=\"non-scaling-stroke\"/>"},
		}},
		{Title: "Tools", Items: []learnItem{
			{Use: "xmllint --noout file.xml", Keys: []string{"xmllint", "--noout", "--schema", "--relaxng"}, Why: "Checks a file and prints only its errors (libxml2). --schema or --relaxng also checks it against a schema.",
				Like: "Like a spell checker that only speaks up when something is wrong.", Example: "xmllint --noout config.xml\nxmllint --noout --schema config.xsd config.xml"},
			{Use: "SVGO", Keys: []string{"svgo"}, Why: "A Node.js command-line tool and library that optimizes SVG files. Each of its default plugins can be changed or turned off.",
				Like: "Like packing a suitcase again, tightly, with nothing left out that you need.", Example: "npx svgo icon.svg -o icon.min.svg\nnpx svgo -f icons -o dist/icons"},
			{Use: "image/svg+xml", Keys: []string{"content-type", "mime", "svgz"}, Why: "The media type a server should send for .svg files. With the wrong type, browsers may show the code as text.",
				Like: "Like the label 'fragile, glass' on a parcel: it tells the receiver how to open it.", Example: "Content-Type: image/svg+xml\n<object data=\"logo.svg\" type=\"image/svg+xml\"></object>"},
		}},
		{Title: "Avoid", Items: []learnItem{
			{Use: "xlink:href", Keys: []string{"xlink", "xmlns:xlink"}, Why: "Deprecated in SVG 2. Write href without a prefix.",
				Like: "Like an old street name: people may still know it, but new signs use the new one.", Example: "<!-- instead: -->\n<use href=\"#icon\"/>"},
			{Use: "version=\"1.1\" · baseProfile", Keys: []string{"version", "baseprofile"}, Why: "SVG 2 removed these attributes from the svg element.",
				Like: "Like a stamp on a letter that the post office no longer reads.", Example: "<!-- instead: -->\n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\">"},
			{Use: "<!DOCTYPE … <!ENTITY", Keys: []string{"doctype", "entity", "system", "dtd"}, Why: "Turn off DTDs in parsers that read untrusted XML. External entities can read server files (XXE). Entity expansion can also exhaust memory. SVG 2 needs no doctype.",
				Like: "Like a letter that says 'also open the parcel in the back room': a stranger should not decide what you open.", Example: "# instead:\nimport defusedxml.ElementTree as ET\ntree = ET.parse(\"upload.xml\")"},
			{Use: "a bare & or <", Why: "A raw & or < in text or in an attribute value breaks the document. Write &amp; and &lt;.",
				Like: "Like a stray full stop in a sentence: the reader thinks it ends there.", Example: "<!-- instead: -->\n<a href=\"/search?q=tea&amp;page=2\">Tom &amp; Jerry</a>"},
			{Use: "-- inside <!-- -->", Why: "Two hyphens are not allowed inside a comment. Use one hyphen, or another character.",
				Like: "Like writing 'the end' in the middle of a story: the reader stops too early.", Example: "<!-- instead: -->\n<!-- Build step - run before deploy -->"},
			{Use: "<use href=\"data:…\">", Why: "Data URIs in the href of <use> are deprecated for security reasons. Reference an id or a file instead.",
				Like: "Like accepting a key posted to you by a stranger: it is safer to use one from your own keyring.", Example: "<!-- instead: -->\n<use href=\"icons.svg#star\"/>"},
		}},
	},
}
